// Lane-local repair generators. Preserve screen IDs, positions and existing navigation.
var APP;
function all(l){var a=[l];(l.layers||[]).forEach(k=>a=a.concat(all(k)));return a;}
function named(l,n){return all(l).find(k=>k.name===n);}
function texts(l){return all(l).filter(k=>k.type==='Text');}
function replace(l,a,b){texts(l).filter(t=>t.text===a).forEach(t=>t.text=b);}
function clear(l){l.layers.slice().forEach(k=>k.remove());}
function col(p,n,w,g,pad,fill,h){var f=H.frame({parent:p,name:n,dir:'col',w:w,h:h,gap:g===undefined?16:g,pad:pad||0,fill:fill?H.sw(APP,fill):null});f.stackLayout.alignItems=0;return f;}
function row(p,n,w,g,pad,fill,h){return H.frame({parent:p,name:n,dir:'row',w:w,h:h,gap:g===undefined?8:g,pad:pad||0,fill:fill?H.sw(APP,fill):null});}
function tx(p,t,size,role,w,weight){return H.text({parent:p,text:t,size:size||14,color:H.sw(APP,role||'ink'),w:w,weight:weight||5});}
function space(p,vert){var f=H.frame({parent:p,name:'flex-space',w:1,h:1});f[vert?'verticalSizing':'horizontalSizing']=sketch.FlexSizing.Fill;return f;}
function btn(p,t,id,kind,w,h){var b=row(p,'link:'+id,w,8,{left:12,right:12,top:0,bottom:0},kind==='primary'?'ink':'surface',h||36);b.style.corners.radii=[8,8,8,8];b.style.borders=[{color:H.sw(APP,'line'),thickness:1,position:sketch.Style.BorderPosition.Inside}];b.stackLayout.justifyContent=1;tx(b,t,13,kind==='primary'?'inverse':kind==='danger'?'negative':'ink',undefined,6);H.order(b);return b;}
function ib(p,icon,id){var b=row(p,'link:'+id,32,0,0,null,32);b.stackLayout.justifyContent=1;H.icon({parent:b,d:H.paths[icon],size:18,color:H.hex(APP,'secondary')});H.order(b);return b;}
function card(p,n,w,g,pad){var c=col(p,n,w,g===undefined?16:g,pad===undefined?20:pad,'surface');c.style.corners.radii=[12,12,12,12];c.style.borders=[{color:H.sw(APP,'line'),thickness:1,position:sketch.Style.BorderPosition.Inside}];return c;}
function mono(p,t,w){return H.text({parent:p,text:t,size:12,mono:true,color:H.sw(APP,'secondary'),w:w});}
function utility(s){all(s).filter(l=>l.name==='link:search'&&l.type==='Group').forEach(b=>{b.style.fills=[{color:H.sw(APP,'surface'),enabled:true}];b.style.borders=[{color:H.sw(APP,'line'),thickness:1,position:sketch.Style.BorderPosition.Inside}];texts(b).forEach(t=>t.style.textColor=H.sw(APP,'ink'));});var f=named(s,'sidebar');var foot=f&&named(f,'link:settings');if(foot){foot.stackLayout.gap=6;foot.stackLayout.apply();}}
function normalized(s){all(s).forEach(l=>{if(/^link:.* \d+$/.test(l.name))l.name=l.name.replace(/ \d+$/,'');});}
function final(s){utility(s);H.relayout(s);normalized(s);H.out({screen:s.name,id:s.id,frame:s.frame,links:all(s).filter(l=>l.name.startsWith('link:')).map(l=>l.name)});}
function edit(id,fn){['Light','Dark'].forEach(a=>{APP=a+'/Clean';var s=H.page('Proto macOS '+a).layers.find(l=>l.name==='Screen/macos/'+APP+'/'+id);if(!s)throw Error('Missing '+id);var x=s.frame.x,y=s.frame.y;fn(s);final(s);s.frame.x=x;s.frame.y=y;});}

var TARGET="conversation";
edit(TARGET,function(s){
var header=named(s,'header');clear(header);header.stackLayout.padding={left:24,right:24,top:12,bottom:12};var hc=col(header,'conversation-heading',1000,4);tx(hc,'Personal › Conversation',12,'secondary');tx(hc,'Move the billing webhook handler onto the new ledger client',20,'ink',1000,7);H.order(hc);space(header);ib(header,'dots','conversation--menu');H.order(header);
var thread=named(s,'thread');clear(thread);thread.stackLayout.gap=24;thread.stackLayout.padding={top:24,left:32,right:32,bottom:24};var u=card(thread,'user-turn',816,16,16);tx(u,'YOU',11,'tertiary');tx(u,'Move the billing webhook handler onto the new ledger client. Keep the existing behavior and run the webhook tests.',14,'ink',784);H.order(u);
var turn=col(thread,'assistant-turn',816,16);var thought=row(turn,'link:conversation',816);H.icon({parent:thought,d:H.paths.brain,size:16,color:H.hex(APP,'secondary')});tx(thought,'Thought for 12 seconds  ⌄',12,'secondary');H.order(thought);
var tool=row(turn,'link:conversation--approval',816,10,12,'panel',40);H.icon({parent:tool,d:H.paths.terminal,size:16,color:H.hex(APP,'secondary')});mono(tool,'npm test',100);tx(tool,'Webhook tests · Personal',12,'secondary');space(tool);tx(tool,'Approval needed',12,'accent');H.order(tool);
var answer=col(turn,'assistant-markdown',816,16);tx(answer,'Weave',14,'ink',undefined,7);tx(answer,'I’ve isolated the webhook changes, preserving idempotency and signature verification.',14,'ink',816);var code=card(answer,'code-block',816,8,12);var cr=row(code,'code-toolbar',792,8,null,null,24);tx(cr,'TypeScript · services/billing/webhook.ts',11,'secondary');space(cr);var cp=ib(cr,'copy','conversation');cp.frame.height=24;H.order(cr);mono(code,'const ledger = createLedgerClient(config);\nawait ledger.webhooks.process(event, { idempotencyKey: event.id });',792);H.order(code);H.order(answer);
var question=card(turn,'question-card',816,12,12);tx(question,'Run the full suite too?',14,'ink',undefined,7);var qr=row(question,'choices',792,12);btn(qr,'◉ Only webhook tests','conversation');btn(qr,'○ Full suite','conversation');space(qr);btn(qr,'Answer','conversation','primary');H.order(qr);H.order(question);
var work=row(turn,'link:activity--work',816,16,12,'panel',76);var wc=col(work,'work-copy',660,6);tx(wc,'Prepare the release',15,'ink',undefined,7);tx(wc,'Running · Release checks · Verify candidate · 1 / 3 · Workspace sprite · Personal',11,'secondary',660);H.order(wc);btn(work,'Review','activity--work');H.order(work);H.order(turn);
space(thread,true);var composer=card(thread,'composer',816,8,12);tx(composer,'Message…',14,'tertiary');var controls=row(composer,'composer-actions',792);ib(controls,'plus','conversation--menu');btn(controls,'Claude Sonnet 4.5  ⌄','settings-models');space(controls);tx(controls,'PREVIEW',10,'tertiary');ib(controls,'mic','conversation');btn(controls,'↑','conversation','primary',36);H.order(controls);var notice=tx(composer,'Voice needs this Mac enrolled. Add it in Settings under Devices.\nVoice is a preview. Each call ends after 5 minutes; start a new call to continue.',11,'secondary',792);notice.name='link:settings-devices';H.order(composer);H.order(thread);
var ins=named(s,'context-inspector');ins.stackLayout.gap=16;ins.layers.filter(l=>l.name==='link:artifacts'&&l.type==='Group').forEach(b=>{var t=texts(b)[0].text;clear(b);b.frame.height=28;b.stackLayout.justifyContent=0;H.icon({parent:b,d:H.paths.file,size:14,color:H.hex(APP,'secondary')});tx(b,t,12,'ink');H.order(b);});
});